def first_unique_index(text):
    char_count = {}
    for i, char in enumerate(text):
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1
    for i, char in enumerate(text):
        if char_count[char] == 1:
            return i
    return -1

def safe_join(base, user_path):
    if user_path.startswith('/'):
        raise ValueError("Absolute paths are not allowed")
    if user_path.endswith('/'):
        user_path = user_path[:-1]
    if '..' in user_path.split('/'):
        raise ValueError("Path traversal attempts are not allowed")
    if user_path == '':
        return base
    split_base = base.split('/')
    split_user_path = user_path.split('/')
    for i, part in enumerate(split_user_path):
        if part == '..':
            if len(split_base) > 0:
                split_base.pop()
        else:
            split_base.append(part)
    result = '/'.join(split_base)
    if result.startswith('/'):
        result = result[1:]
    return result

def evaluate_rpn(tokens):
    """
    Evaluates a Reverse Polish Notation (RPN) expression.
    Supports +, -, *, / and integers. Division must truncate towards zero.
    Raises ValueError for invalid expressions or division by zero.
    """
    stack = []
    for token in tokens:
        if token.isdigit() or (token[0] == '-' and token[1:].isdigit()):
            stack.append(int(token))
        elif token in '+-*/':
            if len(stack) < 2:
                raise ValueError("Invalid expression")
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            elif b == 0:
                raise ValueError("Division by zero")
            else:
                stack.append(int(a / b))
        else:
            raise ValueError("Invalid token in expression")
    if len(stack) != 1:
        raise ValueError("Invalid expression")
    return stack[0]

